window.MONSTER_CHUNK_58 = [{"name":"Shadow Demon","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":18,"ac_touch":18,"ac_flat_footed":14,"ac_mods":"+4 deflection, +4 Dex","hp":59,"hd":"7d10+21","hdvalue":7,"fort":5,"ref":11,"will":7,"defensive_abilities":["incorporeal"],"dr":"10/cold iron or good","immunities":["cold","electricity","poison"],"resists":[{"type":"acid","value":10},{"type":"fire","value":10}],"sr":17,"weaknesses":["sunlight powerlessness"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"2 claws +11 touch (1d6 plus 1d6 cold), bite +11 touch (1d8 plus 1d6 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"pounce"},{"type":"sprint"},{"type":"shadow blend"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"fear"},{"spell":"greater teleport","details":"self only"},{"spell":"telekinesis"}]},{"frequency":"1/day","spells":[{"spell":"magic jar"},{"spell":"summon","details":"level 3, 1 shadow demon 50%"}]},{"frequency":"3/day","spells":[{"spell":"shadow conjuration"},{"spell":"shadow evocation"}]}],"dexterity":18,"constitution":17,"intelligence":14,"wisdom":14,"charisma":19,"baseatk":7,"cmb":11,"cmd":25,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Acrobatics","value":14},{"skill":"Bluff","value":14},{"skill":"Fly","value":22},{"skill":"Knowledge (local)","value":12},{"skill":"Knowledge (planes)","value":12},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":12},{"skill":"Stealth","value":14}],"languages":["Abyssal","Common","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","pair","haunt (3-8)"],"treasure":"standard","description_visual":"Only this shadowy bat-winged demon's teeth and claws have any sense of physicality to them-the rest is lost in darkness.","group":"Demon","source":"PFRPG Bestiary","special_abilities":[{"type":"Sprint","kind":"Ex","details":"Once per minute, a shadow demon increase its fly speed to 240 ft. for 1 round."},{"type":"Shadow Blend","kind":"Su","details":"During any conditions other than bright light, a shadow demon can disappear into the shadows as a moveequivalent action, effectively becoming invisible. Artificial illumination or light spells of 2nd level or lower don't negate this ability."},{"type":"Sunlight Powerlessness","kind":"Ex","details":"A shadow demon is utterly powerless in bright light or natural sunlight and flees from it. A shadow demon caught in such light cannot attack and can take only a single move or standard action. A shadow demon that is possessing a creature using magic jar isn't harmed by sunlight, but if it is struck by a sunbeam or sunburst spell while possessing a creature, the shadow demon is driven out of its host automatically."}],"description":"Tales of demonic possession are common, used often by the ignorant to explain strange or violent behavior. While the majority of such cases are merely manifestations of madness or derangement, those that are legitimate possessions are often the work of shadow demons. Unlike many demons, shadow demons are incorporeal. When a particularly envious and evil mortal soul is pulled into the Abyss, it is transformed, split apart, and combined with other souls until what emerges is little more than jealous malevolence without the impediment of a physical body.","ecology":"","habitat_society":""},{"name":"Shaitan","cr":7,"xp":3200,"alignment":"LN","size":"Large","type":"outsider","subtypes":["earth","extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+1 Dex, +10 natural, -1 size","hp":85,"hd":"9d10+36","hdvalue":9,"fort":10,"ref":4,"will":8,"immunities":["electricity"],"speed":[{"type":"land","speed":20},{"type":"burrow","speed":60},{"type":"climb","speed":20}],"melee":"2 slams +13 (2d6+5) or mwk scimitar +14 (1d8+7/18-20)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"earth mastery"},{"type":"metalmorph"},{"type":"stone curse"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"meld into stone"},{"spell":"plane shift","details":"willing targets to elemental planes, Astral Plane, or Material Plane only"},{"spell":"soften earth and stone"},{"spell":"stone shape"},{"spell":"veil","details":"self only"}]},{"frequency":"1/day","spells":[{"spell":"trans. mud to rock"},{"spell":"trans. rock to mud"}]},{"frequency":"3/day","spells":[{"spell":"quickened glitterdust"},{"spell":"rusting grasp"},{"spell":"stone tell"},{"spell":"stoneskin"},{"spell":"wall of stone"}]}],"strength":20,"dexterity":13,"constitution":19,"intelligence":14,"wisdom":14,"charisma":15,"baseatk":9,"cmb":15,"cmd":26,"feats":[{"feat":"Combat Casting"},{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Power Attack"},{"feat":"Quicken Spell-Like Ability (glitterdust)"}],"skills":[{"skill":"Appraise","value":14},{"skill":"Bluff","value":14},{"skill":"Climb","value":25},{"skill":"Craft (gemcutting)","value":14},{"skill":"Knowledge (engineering)","value":14},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Spellcraft","value":14}],"languages":["Aquan","Auran","Common","Ignan","Terran","telepathy 100 ft."],"sq":[{"type":"stone glide"}],"environments":["any (Plane of Earth)"],"organizations":["solitary","pair","company (3-6)","band (7-12)"],"treasure":"standard (masterwork scimitar)","description_visual":"This being resembles a towering human with skin of polished stone and glittering agate eyes.","group":"Genie","source":"PFRPG Bestiary","special_abilities":[{"type":"Earth Mastery","kind":"Ex","details":"A shaitan gains a +1 bonus on attack and damage rolls and a +2 bonus on opposed Strengthbased checks if both it and its foe are touching the ground. It takes a -4 penalty on attack and damage rolls against airborne or waterborne opponents."},{"type":"Metalmorph","kind":"Su","details":"As a standard action, a shaitan may touch a single metal object of no more than 10 pounds and transform it into any other metal for 1 day."},{"type":"Stone Curse","kind":"Su","details":"If a shaitan wins a bull rush check by 5 or more and pushes its target into a stone barrier, the target must make a DC 19 Reflex save or be forced into the barrier as if the target had cast meld into stone until the victim makes a successful DC 19 Fortitude save as a full-round action to exit the stone. The save DCs are Strength-based."},{"type":"Stone Glide","kind":"Su","details":"This functions as the earth elemental's earth glide ability, except the shaitan can move through stone, dirt, crystal, or metal."}],"description":"Shaitans are boastful and proud genies from the Plane of Earth with flesh of metal, gems, or stone. A shaitan stands about 11 ft. tall and weighs roughly 5,000 pounds. Some shaitans are noble. Often called pashas, they have 18 Hit Dice and gain the spell-like ability earthquake, usable once per day, as well as the ability to grant up to three wishes per day (nongenies only). A noble shaitan's caster level for its spell-like abilities is 18th. Noble shaitans are CR 13.","ecology":"","habitat_society":""},{"name":"Shark-Eating Crab","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"vermin","subtypes":["aquatic"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":10,"ac_flat_footed":18,"ac_mods":"+2 Dex, +10 natural, -2 size","hp":84,"hd":"8d8+48","hdvalue":8,"fort":12,"ref":4,"will":3,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"2 claws +13 (1d8+9 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"constrict","details":"1d8+9"},{"type":"darting claw"}],"strength":29,"dexterity":14,"constitution":22,"wisdom":12,"charisma":2,"baseatk":6,"cmb":17,"cmb_special":"+4 vs. grapple","cmd":29,"cmd_special":"+12 vs. trip","skills":[{"skill":"Perception","value":5},{"skill":"Swim","value":17}],"sq":[{"type":"water dependency"}],"environments":["any water"],"organizations":["solitary","cast (2-8)"],"treasure":"none","description_visual":"This spiny, long-legged crab towers over its surroundings. Its quick and powerful claws thrash wildly, eager for prey.","group":"Crab","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Darting Claw","kind":"Ex","details":"Evolved for snatching fast prey, a shark-eating crab is exceptionally quick with its claws. When making a full attack, if a shark-eating crab misses with both of its claw attacks, it can make an additional claw attack at a -2 penalty against any creature within its reach."}],"description":"Extremely fast and agile for such a large creature, the shark-eating crab preys on predators of the sea. Not limiting its consumption to just sharks, these crabs feed on fast-moving fish like barracudas and tuna, and even mollusks like giant squid. Their hunting skills have evolved over the ages to track the movements of fast creatures swimming above them as the crabs blend into their surroundings.\n\nThe typical shark-eating crab stands 16 ft. tall and weighs just over 4,000 pounds.","ecology":"","habitat_society":""},{"name":"Ship Sentinel","cr":7,"xp":3200,"alignment":"N","size":"Large","type":"construct","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"ship sight"}],"ac":20,"ac_touch":14,"ac_flat_footed":15,"ac_mods":"+5 Dex, +6 natural, -1 size","hp":68,"hd":"7d10+30","hdvalue":7,"fort":2,"ref":7,"will":8,"dr":"5/slashing or piercing","immunities":["construct traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":30}],"melee":"mwk spear +11 (2d6+6 plus salted wound/x3) or  2 slams +10 (1d6+4 plus salted wound)","ranged":"mwk spear +12 (2d6+4 plus salted wound/x3)","space":"10 ft.","reach":"10 ft.","strength":19,"dexterity":21,"wisdom":23,"charisma":16,"baseatk":7,"cmb":12,"cmd":27,"feats":[{"feat":"Improved Initiative","type":"bonus"}],"environments":["any water"],"organizations":["solitary"],"treasure":"none","description_visual":"A larger-than-life wooden carving of a mermaid holding a spear clambers forward, the vibrant paint coating her frame encrusted in years' worth of sea salt.","source":"AP 57","special_abilities":[{"type":"Salted Wound","kind":"Su","details":"Any living creature damaged by a ship sentinel must make a successful DC 16 Fortitude save or take a -1 penalty on attack and damage rolls for 1 round as salty brine drips painfully onto the wound. On a successful critical hit, the target takes an additional 3d6 points of damage as its flesh cracks and withers from dehydration. The save DC is Charisma-based."},{"type":"Ship Sight","kind":"Su","details":"A ship sentinel is treated as having tremorsense out to 100 ft. while onboard a ship, as its senses permeate the vessel's timbers. It can only detect creatures in contact with the vessel or on objects in contact with the vessel. It cannot use this ability to detect creatures not in contact with the ship, even if they are within the ability's 100-foot radius."}],"description":"Ship sentinels are animated constructs that are bound to a specific vessel and to that ship's captain. Crafted to resemble a humanoid figurehead, a ship sentinel normally rests at the prow of its ship, granting good fortune and protection to the crew. But in times of dire need, the captain can also activate the ship sentinel, causing it to spring to life and fight alongside the vessel's crew. Although individual features of ship sentinels may vary, all ship sentinels are made of wood and have the same general statistics.\n\nA ship sentinel stands roughly 6 ft. tall and weighs 400 pounds.\n\nEcology\n\nA ship sentinel's form is carved and shaped by skilled woodworkers, but cannot truly be brought to \"life\" without offerings from the sea. Most spellcasters who endeavor to create these guardians crush a mixture of sand, shells, and valuable pearls and mix it with saltwater and oils, creating a grainy varnish. The carved figure is coated with the solution and then brought to the shores of the sea and affixed to the bowsprit of the craft it will protect. Only then is the construct's creation finally complete. Unlike with most constructs, however, control of the creature doesn't fall to the creator, but rather to the captain of the ship to which it is affixed. If the captain of the ship changes, control of the construct passes to the new captain.\n\nAlthough resistant to most hazards of sea and storm, all ship sentinels eventually wear down after a time and require polishing, cleaning, and recoating with the specially prepared varnish used during the construct's creation. If maintained in this fashion, however, a single ship sentinel can guard a ship-passing from captain to captain-for decades or even centuries.\n\nHabitat & Society\n\nShip sentinels are solitary creations, and a single construct is capable of defending even the largest of ships. Their presence is an undisputed boon to all aboard-though most captains prefer not to speak of their crafts' guardians, preferring to keep the constructs as secret weapons. When the sentinel is needed, the captain must shout a word or short phrase to bring the construct to life. An awakened ship sentinel is able to recognize loyal members of its crew, placing them under its protective wards, and directs its attacks against any living targets that it doesn't ward, though the construct's master can point it toward specific targets.\n\nIn combat, ship sentinels can pulverize flesh and bone with their heavy wooden hands, but normally wield a weapon of some kind-usually a spear, rapier, shortsword, or other light weapon. Stories even exist of elven vessels that armed their ship sentinels with huge bows, or of daring Brevic sea captains who gave their constructs the fabled Aldori dueling swords of their homeland. Regardless of these variations, most weapons used in a ship sentinel's construction draw upon the construct's inherent nimbleness, an agility belied by the figurehead's wooden form. But whether their weapons are forged or natural, all ship sentinels can infuse the sting of seawater and salt air into their blows, wracking their foes with crippling pain.\n\nShip sentinels are resilient foes, their wooden bodies capable of turning aside most attacks that cannot pierce or gouge them. Unfortunately their construction also makes them vulnerable to fire-their greatest weakness-and any magical fire quickly dries a ship sentinel's body to a nearly immobile brittleness.\n\nVariant Ship Sentinels Ship sentinels can be crafted in a wide variety of forms and are often embellished and customized similarly to mundane figureheads. The following are some of these constructs' most common customizations.\n\nBallista Marksman: Some ship sentinels have a light ballista built into their forms; these sentinels are usually designed to look like an archer with an oversized bow, a beauteous lillend, or a cruel erinyes. Such ship sentinels rarely have a melee weapon, resorting instead to slams if unable to use their ballistae to make ranged attacks. Statistics for ballista marksmen are modified as follows: Ranged light ballista +12 (3d8 plus salted wound /19-20).\n\nMariner's Muse: Sculpted to resemble harp-playing angels or armored heralds, a mariner's muse ship sentinel can use the inspire courage effect of a bard's bardic performance once per day for 5 rounds as if it were a 5th-level bard. It always uses all 5 rounds of its performance at the same time and can never use the performance multiple times in 1 day for any duration.\n\nSea Sorcerer: These ship sentinels are often crafted to resemble wizards, sea serpents, or abstract orrery-like sculptures, and possess limited spell-like abilities. They can only use these abilities while onboard a sailing vessel. These spell-like abilities can each be used 3 times per day, and include animate objects, grease, and obscuring mist.\n\nConstruction\n\nA ship sentinel is built from 400 pounds of wood. The creator or a hired artisan must then shape the creature into the desired likeness, usually after a fashion common to the nautical vessels of the region. Afterward, a special varnish is made from a mixture of sand, seawater, crushed pearls and shells, and magically treated oils- the varnish is worth a total of 250 gp and is applied to the entire form. If the creator intends for the ship sentinel to wield a weapon, a masterwork or better version of that weapon must also be supplied.\n\nShip Sentinel\n\nCL 9th; Price 21,250 gp; 21,750 gp (ballista marksman); 23,250 gp (mariner's muse); 25,250 gp (sea sorcerer)\n\nCONSTRUCTION\n\nRequirements Craft Construct, animate object, limited wish, creator must be caster level 9th; Craft (woodworking) check DC 25; Cost 10,750 gp; 11,000 gp (ballista marksman); 11,750 gp (mariner's muse); 12,750 gp (sea sorcerer)","ecology":"A ship sentinel's form is carved and shaped by skilled woodworkers, but cannot truly be brought to \"life\" without offerings from the sea. Most spellcasters who endeavor to create these guardians crush a mixture of sand, shells, and valuable pearls and mix it with saltwater and oils, creating a grainy varnish. The carved figure is coated with the solution and then brought to the shores of the sea and affixed to the bowsprit of the craft it will protect. Only then is the construct's creation finally complete. Unlike with most constructs, however, control of the creature doesn't fall to the creator, but rather to the captain of the ship to which it is affixed. If the captain of the ship changes, control of the construct passes to the new captain.\n\nAlthough resistant to most hazards of sea and storm, all ship sentinels eventually wear down after a time and require polishing, cleaning, and recoating with the specially prepared varnish used during the construct's creation. If maintained in this fashion, however, a single ship sentinel can guard a ship-passing from captain to captain-for decades or even centuries.","habitat_society":"Ship sentinels are solitary creations, and a single construct is capable of defending even the largest of ships. Their presence is an undisputed boon to all aboard-though most captains prefer not to speak of their crafts' guardians, preferring to keep the constructs as secret weapons. When the sentinel is needed, the captain must shout a word or short phrase to bring the construct to life. An awakened ship sentinel is able to recognize loyal members of its crew, placing them under its protective wards, and directs its attacks against any living targets that it doesn't ward, though the construct's master can point it toward specific targets.\n\nIn combat, ship sentinels can pulverize flesh and bone with their heavy wooden hands, but normally wield a weapon of some kind-usually a spear, rapier, shortsword, or other light weapon. Stories even exist of elven vessels that armed their ship sentinels with huge bows, or of daring Brevic sea captains who gave their constructs the fabled Aldori dueling swords of their homeland. Regardless of these variations, most weapons used in a ship sentinel's construction draw upon the construct's inherent nimbleness, an agility belied by the figurehead's wooden form. But whether their weapons are forged or natural, all ship sentinels can infuse the sting of seawater and salt air into their blows, wracking their foes with crippling pain.\n\nShip sentinels are resilient foes, their wooden bodies capable of turning aside most attacks that cannot pierce or gouge them. Unfortunately their construction also makes them vulnerable to fire-their greatest weakness-and any magical fire quickly dries a ship sentinel's body to a nearly immobile brittleness.\n\nVariant Ship Sentinels Ship sentinels can be crafted in a wide variety of forms and are often embellished and customized similarly to mundane figureheads. The following are some of these constructs' most common customizations.\n\nBallista Marksman: Some ship sentinels have a light ballista built into their forms; these sentinels are usually designed to look like an archer with an oversized bow, a beauteous lillend, or a cruel erinyes. Such ship sentinels rarely have a melee weapon, resorting instead to slams if unable to use their ballistae to make ranged attacks. Statistics for ballista marksmen are modified as follows: Ranged light ballista +12 (3d8 plus salted wound /19-20).\n\nMariner's Muse: Sculpted to resemble harp-playing angels or armored heralds, a mariner's muse ship sentinel can use the inspire courage effect of a bard's bardic performance once per day for 5 rounds as if it were a 5th-level bard. It always uses all 5 rounds of its performance at the same time and can never use the performance multiple times in 1 day for any duration.\n\nSea Sorcerer: These ship sentinels are often crafted to resemble wizards, sea serpents, or abstract orrery-like sculptures, and possess limited spell-like abilities. They can only use these abilities while onboard a sailing vessel. These spell-like abilities can each be used 3 times per day, and include animate objects, grease, and obscuring mist.\n\nConstruction\n\nA ship sentinel is built from 400 pounds of wood. The creator or a hired artisan must then shape the creature into the desired likeness, usually after a fashion common to the nautical vessels of the region. Afterward, a special varnish is made from a mixture of sand, seawater, crushed pearls and shells, and magically treated oils- the varnish is worth a total of 250 gp and is applied to the entire form. If the creator intends for the ship sentinel to wield a weapon, a masterwork or better version of that weapon must also be supplied.\n\nShip Sentinel\n\nCL 9th; Price 21,250 gp; 21,750 gp (ballista marksman); 23,250 gp (mariner's muse); 25,250 gp (sea sorcerer)\n\nCONSTRUCTION\n\nRequirements Craft Construct, animate object, limited wish, creator must be caster level 9th; Craft (woodworking) check DC 25; Cost 10,750 gp; 11,000 gp (ballista marksman); 11,750 gp (mariner's muse); 12,750 gp (sea sorcerer)"},{"name":"Shoggti","cr":7,"xp":3200,"alignment":"CE","size":"Large","type":"outsider","subtypes":["chaotic","evil","extraplanar","qlippoth"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+3 Dex, +9 natural, -1 size","hp":80,"hd":"7d10+42","hdvalue":7,"fort":11,"ref":5,"will":9,"defensive_abilities":["uncanny dodge"],"dr":"10/cold iron or lawful","immunities":["cold","poison","mind-affecting effects"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"bite +12 (1d8+6), 4 tentacles +8 (1d4+3 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"braincloud"},{"type":"horrific appearance","details":"DC 15"},{"type":"constrict","details":"1d4+6"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"command"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"dimension door"}]},{"frequency":"3/day","spells":[{"spell":"charm person"},{"spell":"protection from law"}]}],"strength":22,"dexterity":16,"constitution":23,"intelligence":12,"wisdom":19,"charisma":15,"baseatk":7,"cmb":14,"cmb_special":"+4 vs. grapple","cmd":27,"cmd_special":"+4 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Use Magic Device)"},{"feat":"Weapon Focus (tentacles)"}],"skills":[{"skill":"Escape Artist","value":13},{"skill":"Intimidate","value":16},{"skill":"Knowledge (planes)","value":11},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":9},{"skill":"Use Magic Device","value":19}],"languages":["Abyssal","telepathy 100 ft."],"environments":["any (Abyss)"],"organizations":["solitary","pair","slaver band (3-10 plus 6-12 slaves of various races)"],"treasure":"standard","description_visual":"This pale creature has four suckered arms that end in pincers. A gnashing maw gapes in its head between two staring eyes.","group":"Qlippoth","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Braincloud","kind":"Su","details":"Once per round, in place of a melee attack with a tentacle, a shoggti can make a melee touch attack with the pincer on the end of that tentacle. If it hits, the target takes 1d4 points of Wisdom damage. Shoggti use this ability to mentally debilitate their victims so they can more easily use their charm spell-like abilities against them."},{"type":"Horrific Appearance","kind":"Su","details":"Creatures that succumb to a shoggti's horrific appearance become fascinated by the creature's hypnotically wriggling tentacles and the strange, shimmering colors in its eyes. This effect persists for 1d6 rounds (but can be ended by the normal methods of defeating the fascinated condition)."}],"description":"The shoggti are masters of mind manipulation, capable of seizing control of the thoughts of others and charming them into docile allies. They invade other realms in slaver bands, seeking out creatures to capture alive and return to the Abyss as charmed slaves-the fates of these poor souls is unknown, but likely has something to do with the qlippoth drive to reclaim the Abyss as their own.\n\nAlthough a shoggti lacks proper hands, it is capable of performing incredibly dextrous manipulations with the pincers at the tips of its tentacles. It cannot wield weapons in these pincers, but it can utilize magic items like wands, rods, staves, and the like. Shoggti are fond of wands in particular, particularly those that create mind-affecting effects that are easy to inf lict on victims of their braincloud ability.\n\nA shoggti's body is an egg-shaped mass about 8 ft. long-its tentacles are about 8 ft. long as well. The whole creature weighs 900 pounds.","ecology":"","habitat_society":""},{"name":"Slag Giant","cr":7,"xp":3200,"alignment":"LN","size":"Large","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"low-light vision"}],"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+3 armor, +1 Dex, +7 natural, -1 size","hp":85,"hd":"10d8+40","hdvalue":10,"fort":11,"ref":6,"will":4,"defensive_abilities":["rock catching"],"resists":[{"type":"fire","value":30}],"speed":[{"type":"land","speed":40}],"melee":"warhammer +15 (2d6+12/x3) or 2 slams +14 (1d8+8)","ranged":"rock +8 (1d8+8)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"120 ft."}],"strength":27,"dexterity":12,"constitution":19,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":7,"cmb":16,"cmb_special":"+2 vs. sunder","cmd":29,"cmd_special":"+2 vs. sunder","feats":[{"feat":"Improved Sunder"},{"feat":"Lightning Reflexes"},{"feat":"Martial Weapon Proficiency (warhammer)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (warhammer)"}],"skills":[{"skill":"Craft (armor)","value":12},{"skill":"Craft (weapons)","value":12},{"skill":"Intimidate","value":8},{"skill":"Perception","value":9}],"languages":["Common","Giant"],"sq":[{"type":"shattering blow"}],"environments":["any underground","warm mountains"],"organizations":["solitary","pair","mining expedition (3-7)","tribe (5-20 plus 25% noncombatants and 1 cleric, or 1 fighter of 4th to 6th level plus 1-3 giant frilled lizards)"],"treasure":"standard (warhammer, studded leather)","description_visual":"Soot, ash, and coal dust streak this giant's rust-colored skin. Her eyes hold a look of both determination and detachment.","group":"Giant","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Shattering Blow","kind":"Ex","details":"A slag giant who makes a full attack against a metal or stone object or structure deals double damage."}],"description":"Magically crafted and crossbred from fire giants and stone giants by ancient wizards, slag giants are among the foremost artisans and crafters of giantkind. Proportioned more like stone giants than fire giants, slag giants have long limbs with lean muscles; they stand 14 ft. tall and weigh 3,000 pounds. Slag giants' skin color ranges from a deep and ruddy hue to a rusty orange. Their hair is black, gray, or white, though males and females both tend to keep their hair cropped close or shaved off. Slag giants can live to be 400 years old. Slag giants usually evince a cold, detached attitude about everything other than their work. Their inherent understanding of metalworking and resistance to fire allow them to craft arms and armor from inside their huge forges, sometimes working the metal with their bare hands. Small families of slag giants often ally with clans of other giants, providing masterwork armor and weapons in exchange for ore and the freedom to practice their crafting skills in peace. Even militaristic fire giants (who pride themselves on their strength and martial prowess) respect the fine work of the weaker slag giants, and usually attempt to ally with the artisans rather than enslaving them. Slag giant settlements usually consist of several stone homes (built from or surrounded by forge slag) with built-in forges and large, smoking chimneys. Most are in hills or mountains, but they can be found anywhere there is a ready supply of iron ore. Although they prefer creation to combat, slag giants are brutal and efficient fighters, capable of destroying an enemy's weapons or armor in a few precise blows. They often let opponents retreat if it gives the giants the opportunity to collect any broken weapons and armor as salvage. If approached peacefully, they are willing to barter or sell their goods, though they usually don't have human-sized items on hand. Trespassers who carelessly or wantonly destroy a slag giant's work or foul its forge usually end up in the fire. Most settlements have several giant-sized breastplates the residents can don if they expect a serious fight.","ecology":"","habitat_society":""},{"name":"Soul Eater","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["evil","extraplanar"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"all-around vision"}],"ac":21,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+6 Dex, +1 dodge, +4 natural","hp":82,"hd":"11d10+22","hdvalue":11,"fort":5,"ref":13,"will":7,"dr":"10/magic","immunities":["critical hits","paralysis","poison","sleep","stunning"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":100,"maneuverability":"perfect"}],"melee":"2 claws +18  (1d6+1/19-20 plus 1d6  Wisdom damage)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"find target"},{"type":"soul drain"}],"strength":13,"dexterity":22,"constitution":14,"intelligence":12,"wisdom":11,"charisma":11,"baseatk":11,"cmb":12,"cmd":29,"cmd_special":"can't be tripped","feats":[{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":20,"special":"+8 jump"},{"skill":"Escape Artist","value":20},{"skill":"Fly","value":28},{"skill":"Intimidate","value":14},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":14},{"skill":"Stealth","value":20,"special":"+28 darkness or smoke"}],"languages":["Abyssal","Infernal"],"sq":[{"type":"caster link"}],"environments":["any Outer Plane (Abaddon)"],"organizations":["solitary"],"treasure":"none","description_visual":"Two elongated and deathly pallid arms protrude from this creature's smoky body as it slithers silently through the air.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Caster Link","kind":"Ex","details":"When a soul eater is summoned, it creates a mental link between itself and its conjurer. If the soul eater's assigned target (see find target ability) dies before the soul eater can drain its soul, or if the soul eater is defeated by its target (but not slain), it returns to its conjurer at full speed and attacks her. While the soul eater and the conjurer are on the same plane (regardless of plane-traveling interruptions), it can use its find target ability to locate its conjurer."},{"type":"Find Target","kind":"Su","details":"When a soul eater's conjurer orders it to find a creature, it can do so unerringly, as though guided by a locate creature spell that has no maximum range and isn't blocked by running water. The conjurer must have seen the desired target and must speak the target's name."},{"type":"Soul Drain","kind":"Su","details":"If the Wisdom damage from a soul eater's claw attacks equals or exceeds an opponent's actual Wisdom score, rendering the victim helpless, the soul eater can devour that creature's soul as a standard action that provokes an attack of opportunity. This attack kills the victim. The dead victim can resist having her soul eaten by making a (DC 17) Fortitude save; success means she is still dead, but can be restored to life normally. If she fails this save, her soul is consumed by the soul eater. A victim slain in this manner cannot be returned to life with clone, raise dead, or reincarnation. She can be restored to life via resurrection, true resurrection, miracle, or wish, but only if the caster can succeed on a DC 30 caster level check. If the soul eater is killed within 120 ft. of its victim's corpse, and the victim has been dead for no longer than 1 minute, the victim's soul returns to her body and restores her to life, leaving her unconscious and at - 1 hit point. This is a death effect. The save DC is Constitution-based."},{"type":"Wisdom Damage","kind":"Su","details":"A creature hit by a soul eater's claw must succeed on a DC 17 Fortitude save or take 1d6 points of Wisdom damage. The save DC is Constitution-based."}],"description":"Summoned forth from the inky swamps of Abaddon, a soul eater is an extraplanar entity devoid of emotion or reason and possessing a hunger that may only be sated by devouring the souls of the living. The very nature of a soul eater makes it an ideal and terrifyingly efficient tool of death, and it is for this reason they are often conjured by vile spellcasters pursuing morbid agendas. Even when not seeing to the heinous commands of a sinister magic user, the soul eater prowls and hunts, constantly seeking living souls upon which to gorge itself.","ecology":"","habitat_society":""},{"name":"Soulbound Mannequin","cr":7,"xp":3200,"alignment":"N","size":"Medium","type":"construct","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":85,"hd":"10d10+30","hdvalue":10,"fort":3,"ref":6,"will":3,"dr":"5/magic","immunities":["construct traits"],"weaknesses":["susceptible to mind-affecting effects"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +15 (1d8+4 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"1d8+4"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"detect poison"},{"spell":"light"},{"spell":"mage hand"},{"spell":"open/close"},{"spell":"prestidigitation"}]},{"frequency":"1/day","spells":[{"spell":"disguise self","details":"see below"},{"spell":"levitate"}]},{"frequency":"3/day","spells":[{"spell":"alarm"},{"spell":"feather fall"},{"spell":"hold portal"}]}],"strength":18,"dexterity":16,"intelligence":11,"wisdom":10,"charisma":9,"baseatk":10,"cmb":14,"cmb_special":"+4 vs. grapple","cmd":27,"feats":[{"feat":"Improved Initiative"},{"feat":"Martial Weapon Proficiency (any one)"},{"feat":"Throw Anything"},{"feat":"Toughness"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Intimidate","value":9},{"skill":"Perception","value":10}],"languages":["Common"],"sq":[{"type":"alignment variation"},{"type":"soul focus"}],"environments":["any land"],"organizations":["solitary","pair","family (3-12)"],"treasure":"standard","description_visual":"This strange construct is shaped like a masked humanoid made of wood and porcelain.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Alignment Variation","kind":"Ex","details":"Soulbound mannequins are at least partially neutral in alignment, although they can also be chaotic, evil, good, or lawful. They have an alignment-dependent spell-like ability usable once per day as listed below. • Chaotic Neutral: confusion (DC 13) • Lawful Neutral: fear (DC 13) • Neutral: hold monster (DC 13) • Neutral Evil: enervation • Neutral Good: greater invisibility."},{"type":"Disguise Self","kind":"Sp","details":"The soulbound mannequin can only disguise itself as the living person it used to be at approximately the age it was when its soul was used to make the mannequin (this allows it to take the appearance of another creature type)."},{"type":"Soul Focus","kind":"Su","details":"The soul bound to the mannequin lives within a focus integrated into the doll or its apparel, typically a carved mask. As long as this soul focus remains intact, it can be used to animate another mannequin, at the same cost as creating a new soulbound mannequin. The new mannequin retains its personality and memories. A soul focus has hardness 8, 12 hit points, and a break DC of 20."},{"type":"Susceptible to Mind-Affecting Effects","kind":"Ex","details":"Unlike most constructs, a soulbound mannequin isn't immune to mind-affecting effects."}],"description":"A soulbound mannequin is a human-sized improvement on the soulbound doll. The binding process is sophisticated enough to leave much of the soul's personality intact. Most are crafted to allow a faithful servant to remain with a prestigious family or to allow a dying loved one to remain among the living in a limited way. Because the mannequin's face is expressionless and its voice has little inf lection, it carries several masks that it uses to convey emotions. It often serves its creator as a bodyguard, companion, servant, sentry, or even paramour.\n\nConstruction\n\nA soulbound mannequin is made from wood or porcelain, with one expertly carved mask worth at least 500 gp to serve as the soul focus. Creation requires a soul fragment from a creature who dies at some point during the creation of the mannequin (this doesn't prevent the rest of the soul from continuing on to the afterlife or prevent the body from later being revived). An unwilling soul can resist the procedure with a successful DC 20 Will save.\n\nSOULBOUND MANNEQUIN\n\nCL 7th; Price 16,500 gp\n\nConstruction\n\nRequirements Craft Construct, disguise self, false life, lesser geas, magic jar, minor creation, soul of a living creature who dies or is slain during the creation process; Skill Craft (sculptures); Cost 8,500 gp","ecology":"","habitat_society":""},{"name":"Spectre","cr":7,"xp":3200,"alignment":"LE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["unnatural aura (30 ft.)"],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+2 deflection, +3 Dex","hp":52,"hd":"8d8+16","hdvalue":8,"fort":4,"ref":5,"will":9,"defensive_abilities":["incorporeal","channel resistance +2"],"weaknesses":["resurrection vulnerability","sunlight powerlessness"],"speed":[{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"incorporeal touch +10 (1d8 plus energy drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"create spawn"},{"type":"energy drain","details":"2 levels, DC 16"}],"dexterity":16,"intelligence":14,"wisdom":16,"charisma":15,"baseatk":6,"cmb":6,"cmd":21,"feats":[{"feat":"Blind-Fight"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (touch)"}],"skills":[{"skill":"Fly","value":11},{"skill":"Intimidate","value":13},{"skill":"Knowledge (history)","value":10},{"skill":"Knowledge (religion)","value":13},{"skill":"Perception","value":17},{"skill":"Stealth","value":14},{"skill":"Survival","value":11}],"languages":["Common"],"environments":["any"],"organizations":["solitary","pair","gang (3-6)","swarm (7-12)"],"treasure":"none","description_visual":"This translucent, ghostly figure fades into view from the damp mist, its face distorted by wrath into a hideous mask.","source":"PFRPG Bestiary","special_abilities":[{"type":"Create Spawn","kind":"Su","details":"Any humanoids slain by a spectre become spectres themselves in 1d4 rounds. Spawn so created are less powerful than typical spectres, and suffer a -2 penalty on all d20 rolls and checks, receive -2 hp per HD, and only drain one level on a touch. Spawn are under the command of the spectre that created them and remain enslaved until its death, at which point they lose their spawn penalties and become full-fledged and free-willed spectres. They don't possess any of the abilities they had in life."},{"type":"Resurrection Vulnerability","kind":"Su","details":"A raise dead or similar spell cast on a spectre destroys it (Will negates). Using the spell in this way doesn't require a material component."},{"type":"Sunlight Powerlessness","kind":"Ex","details":"Spectres are powerless in natural sunlight (not merely a daylight spell) and flee from it. A spectre caught in sunlight cannot attack and is staggered."},{"type":"Unnatural Aura","kind":"Su","details":"Animals, whether wild or domesticated, can sense the unnatural presence of a spectre at a distance of 30 ft. They don't willingly approach nearer than that and panic if forced to do so unless a master succeeds at a DC 25 Handle Animal, Ride, or wild empathy check. A panicked animal remains so as long as it is within 30 ft. of the spectre."}],"description":"Spectres are evil undead that hate sunlight and living things. Most are the remnants of murdered or evil humans, their anger preventing them from entering the afterlife. Like ghosts, spectres haunt the places of their deaths, and seek to draw others into the lonely abyss of undeath. A spectre looks much as it did in life and can be easily recognized by those who knew the individual or have seen the individual's face in paintings or drawings. Spectres retain a strong sense of identity, and even ancient, insane spectres generally remain coherent. Evil historians and necromancers often try to ally with spectres for the knowledge they held in life and retain in undeath.","ecology":"","habitat_society":""},{"name":"Spellscar Fext","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"undead","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":85,"hd":"10d8+40","hdvalue":10,"fort":7,"ref":6,"will":8,"dr":"5/cold iron","immunities":["undead traits"],"sr":18,"weaknesses":["vulnerable to glass"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +14 (1d6+7/18-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"deadly slam"},{"type":"dispelling critical"}],"strength":25,"dexterity":16,"intelligence":8,"wisdom":13,"charisma":19,"baseatk":7,"cmb":14,"cmd":27,"feats":[{"feat":"Cleave"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":16},{"skill":"Intimidate","value":12},{"skill":"Perception","value":14},{"skill":"Stealth","value":18}],"languages":["Common"],"sq":[{"type":"ravage magic"}],"environments":["any (Spellscar Desert)"],"organizations":["solitary","pair","hunt (3-5)"],"treasure":"standard","description_visual":"This undead horror's upper body is twisted and malformed, and its hands end in tangles of blunt, electric-blue tendrils.","source":"Inner Sea Bestiary","special_abilities":[{"type":"Deadly Slam","kind":"Ex","details":"A Spellscar fext threatens a critical hit with its slam attack on rolls of 18-20."},{"type":"Dispelling Critical","kind":"Su","details":"Whenever a Spellscar fext successfully scores a critical hit with its slam attack, the creature struck must succeed at a DC 19 Will save or be affected as though by the targeted dispel version of a dispel magic spell (caster level 10th). The save DC is Charisma-based."},{"type":"Ravage Magic","kind":"Su","details":"Any targeted spell or spell-like ability that fails to penetrate a Spellscar fext's spell resistance is absorbed by the fext and warped into a form of primal magic. A Spellscar fext can twist only a number of spell levels per round equal to its Charisma modifier (4 for most Spellscar fexts); any spells in excess of this limit automatically bypass a Spellscar fext's spell resistance and don't trigger this ability. Roll on the following table to determine the effect of a spell that has been affected by a Spellscar fext's ravage magic ability. Alternatively, a Spellscar mutant may use any of the sample primal magic events found effects with the CR of the Spellscar fext. d% Effect 01-40 The spell has no effect. 41-70 The Spellscar fext emits a burst of negative energy, dealing a number of points of negative energy damage equal to 1d6 x the spell level of the triggering spell to all creatures in a 30-foot-radius burst. 71-90 The Spellscar fext instantly switches places with the spellcaster that targeted the fext with the triggering spell as though by dimension door. 91-100 The spell is immediately turned back on its caster via spell turning."},{"type":"Vulnerable to Glass","kind":"Ex","details":"A Spellscar fext's hide is particularly vulnerable to the penetrations of glass and glass-based weapons. Spellscar fexts take 150% as much damage as normal from glass-headed piercing or slashing weapons."}],"description":"The abominable undead known as Spellscar fexts are formed by wayward spellcasters who perish in the sprawling badlands of the Mana Wastes, their bodies and souls perverted by the unpredictable primal energies that surge throughout the Spellscar Desert. The average Spellscar fext stands about 6 ft. tall and weighs 200 pounds.\n\nThe unnatural and corruptive transformations a fallen victim undergoes as it turns into a Spellscar fext render its body hard and especially resilient to the magical energies of most spellcasters. In a peculiar twist, the same corruptive energy that causes spells to bounce off of Spellscar fexts' hides also strangely renders them susceptible to glass and glass-based weapons. Talented gunsmiths from Alkenstar have managed to craft glass bullets for rifle-wielding adventurers and monster hunters for the purpose of eradicating Spellscar fexts.","ecology":"","habitat_society":""},{"name":"Spire Drake","cr":7,"xp":3200,"alignment":"LE","size":"Large","type":"dragon","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":10,"ac_flat_footed":19,"ac_mods":"+1 Dex, +10 natural, -1 size","hp":84,"hd":"8d12+32","hdvalue":8,"fort":10,"ref":7,"will":6,"immunities":["curses","energy drain","negative energy","paralysis","sleep"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"bite +13 (2d6+6 plus 1d6 negative energy), tail slap +8 (1d8+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"accursed breath"},{"type":"soul corruption"}],"strength":22,"dexterity":12,"constitution":19,"intelligence":10,"wisdom":11,"charisma":15,"baseatk":8,"cmb":15,"cmd":26,"feats":[{"feat":"Flyby Attack"},{"feat":"Power Attack"},{"feat":"Vital Strike"},{"feat":"Wingover"}],"skills":[{"skill":"Climb","value":20},{"skill":"Fly","value":10},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (religion)","value":10},{"skill":"Perception","value":11},{"skill":"Spellcraft","value":10},{"skill":"Use Magic Device","value":13}],"languages":["Draconic"],"sq":[{"type":"speed surge"}],"environments":["any hills"],"organizations":["solitary","pair","rampage (3-12)"],"treasure":"standard","description_visual":"This reptilian creature's gaunt body, legs, and batlike face are covered in long spines. Two wings stretch out from its torso.","group":"Drake","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Accursed Breath","kind":"Su","details":"As a standard action, a spire drake can spit a compressed ball of jet-black dust that bursts into a spray of clinging motes that sap the spiritual strength of creatures in an area. The attack has a range of 60 ft. and deals 5d6 points of negative energy damage (Will DC 18 half) to all creatures in a 20-foot radius. Affected creatures take a -2 penalty on attack rolls, saving throws, skill checks, and ability checks for 1d4 rounds (or for 1 round on a successful Will save). As long as these motes cling to a creature, the effect of any conjuration (healing) effect used on that creature is halved. This is a curse effect. The save DC is Constitution-based."},{"type":"Soul Corruption","kind":"Su","details":"If a spire drake successfully performs a coup de grace upon a creature afflicted by its accursed breath, the slain target arises 1d4 rounds later as a wight. This wight isn't under the drake's control, and the wight and any spawn that it creates perish 1d6 days after arising."},{"type":"Speed Surge","kind":"Su","details":"Three times per day as a swift action, a spire drake can draw on its draconic reserves for a boost of strength and speed, allowing it to take an additional move action in that round."}],"description":"Sages attribute the gaunt builds and tattered, scabrous wings of spire drakes to centuries of dwelling in magic-blasted desolations and accursed badlands, positing that the tainting of the land seeps into the drakes' flesh and bone and into every clutch of eggs, and is thus carried down through generations of decay. But while their appearance is somewhat withered, spire drakes are just as strong and ferocious as other drakes. Spire drakes are unusually intelligent for their kind. They are particularly curious about magic and magical items, and enjoy having large collections of such items even if they don't know how to use them. Lacking the ability to detect magic, they often scour their hunting ranges for any items they suspect might be magical, collecting an array of strange and obscure devices and objects and displaying them proudly so they can boast to other drakes they encounter (who often jealously try to steal or destroy the collections of their rivals). Spire drakes often demand tribute from merchants and caravans passing through or near the lands they claim, or may offer to let opponents escape a fight in exchange for surrendering a magic item. Spire drakes are rarely as clever as they think, however, and can be easily tricked by temporary magical effects into believing an item is magical. Still, spire drakes that manage to collect true magical items use them offensively or defensively as appropriate, and love to show off their latest prizes. A typical spire drake measures 18 ft. from its nose to the long, thin tip of its tail, and weighs about 1,700 pounds.","ecology":"","habitat_society":""},{"name":"Steam Hog","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"magical beast","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":19,"ac_touch":8,"ac_flat_footed":19,"ac_mods":"+5 armor, +6 natural, -2 size","hp":94,"hd":"9d10+45","hdvalue":9,"fort":10,"ref":6,"will":6,"defensive_abilities":["ferocity"],"dr":"2/-","resists":[{"type":"fire","value":15}],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":10}],"melee":"gore +14 (2d6+7 plus 1d6 fire), 2 hooves +9 (1d8+3)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"steam cloud"},{"type":"trample","details":"1d8+10, DC 21"}],"strength":24,"dexterity":11,"constitution":18,"intelligence":1,"wisdom":12,"charisma":9,"baseatk":9,"cmb":18,"cmd":28,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":10},{"skill":"Perception","value":10}],"environments":["warm mountains"],"organizations":["solitary","cavalry (2-4 plus 2-4 fire giants)","stampede (5-8 plus 3-8 fire giants)"],"treasure":"standard (Huge adamantine scale mail barding)","description_visual":"This massive warthog is outfitted with all manner of steel armor and unnatural augmentations, including a pair of razor-sharp metal tusks.","source":"Monster Codex","special_abilities":[{"type":"Steam Cloud","kind":"Ex","details":"As a standard action, a steam hog can emit a cloud of steam from its snout in a 10-foot-radius spread. The initial burst of steam deals 2d6 points of fire damage to any creature in the area. The cloud remains for 1d4 rounds once created, acting as a 10-foot-radius obscuring mist. Any creature that begins its turn in the area of the steam must succeed at a DC 18 Fortitude save or take 1d6 points of fire damage. A steam hog can use its steam cloud only once every 1d6 rounds. The save DC is Constitution-based."}],"description":"The military advancements of fire giants aren't restricted only to arms and armor-just as ore is dredged from the mountains for these giants' cruel forges, animals are culled from the wilds to serve as fire giant weaponry. In addition to using hell hounds, red dragons, and other fiery fauna for their brutal campaigns, fire giants have created several unique species of war beasts all their own. Chief among these amalgamations of flesh and steel are the malformed swine known as steam hogs-enormous snorting brutes charged with heading the front lines of fire giant armies, each one capable of laying low an entire platoon of enemy soldiers.\n\nWhile fire giants are more than capable of crafting new armor for their steam hogs, they take great pleasure in bedecking their prized war beasts with the reforged arms and armor of their vanquished foes. In this way, the armor and accoutrements of a veteran steam hog serve as a record of the battles and wars the beast has fought in. When such a steam hog falls in battle, its armor-and thus its history-are often kept by sentimental fire giant handlers as treasured heirlooms.\n\nSteam hogs average 16 ft. long from snout to tail and 8 ft. tall at the shoulder. They can weigh up to 3 tons, or 4 tons when equipped with adamantine scale barding.","ecology":"","habitat_society":""},{"name":"Stegosaurus","cr":7,"xp":3200,"alignment":"N","size":"Huge","type":"animal","init":6,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":22,"ac_touch":10,"ac_flat_footed":20,"ac_mods":"+2 Dex, +12 natural, -2 size","hp":90,"hd":"12d8+36","hdvalue":12,"fort":13,"ref":10,"will":5,"speed":[{"type":"land","speed":30}],"melee":"tail +16 (4d6+12 plus trip)","space":"15 ft.","reach":"15 ft.","strength":27,"dexterity":14,"constitution":17,"intelligence":2,"wisdom":13,"charisma":10,"baseatk":9,"cmb":19,"cmd":31,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Improved Overrun"},{"feat":"Power Attack"},{"feat":"Weapon Focus (tail)"}],"skills":[{"skill":"Perception","value":16}],"environments":["warm plains"],"organizations":["solitary","pair","herd (3-12)"],"treasure":"none","description_visual":"This huge dinosaur has a small head, twin rows of sharp dorsal plates, and a muscular tail terminating in a set of bony spikes.","group":"Dinosaur","source":"PFRPG Bestiary","description":"The stegosaurus is one of the most distinctive-looking dinosaurs-its twin rows of dorsal plates and spiked tail are enough to give most predators second thoughts before attacking. It is 30 ft. long, 14 ft. tall, and weighs 5,000 pounds. Stegosaurus Companions Starting Stats: Size Med.; Speed 30 ft.; AC +6 natural armor; Attack tail (2d6); Ability Scores Str 10, Dex 18, Con 10, Int 2, Wis 12, Cha 10; Special Qualities lowlight vision, scent. 7th-Level Adv: Size Large; AC +3 natural armor; Attack tail (2d8 plus trip); Ability Scores Str +8, Dex -2, Con +4.","ecology":"","habitat_society":""},{"name":"Storm Hag","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"monstrous humanoid","init":2,"senses":[{"type":"child-scent"},{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+2 Dex, +1 dodge, +8 natural","hp":85,"hd":"10d10+30","hdvalue":10,"fort":6,"ref":9,"will":8,"immunities":["electricity"],"sr":18,"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"good"}],"melee":"bite +13 (1d6+3 plus 1d6 electricity), 2 claws +13 (1d4+3 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"storm strike"},{"type":"whipping winds"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"bleed"},{"spell":"gust of wind"},{"spell":"whispering wind"}]},{"frequency":"1/day","spells":[{"spell":"control winds"}]},{"frequency":"3/day","spells":[{"spell":"invisibility"},{"spell":"lightning bolt"},{"spell":"river of wind"},{"spell":"sleet storm"}]}],"strength":17,"dexterity":14,"constitution":16,"intelligence":13,"wisdom":13,"charisma":16,"baseatk":10,"cmb":13,"cmd":26,"feats":[{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Vital Strike"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Fly","value":17},{"skill":"Intimidate","value":15},{"skill":"Perception","value":14},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":15}],"languages":["Common","Giant"],"sq":[{"type":"storm rider"}],"environments":["any temperate"],"organizations":["solitary","coven (3 hags of any kind)"],"treasure":"standard","description_visual":"Clad in hides and furs, this creature appears to be a small, ugly woman whose hair, claws, and teeth crackle with sparks of electricity. Her windswept hair billows up from her brow like an enormous thunderhead.","source":"AP 72","special_abilities":[{"type":"Child-Scent","kind":"Ex","details":"A storm hag has the scent ability, but only with respect to humanoid children and immature animals. Thus, she could sniff out a child's hiding place or a den of wolf pups, but not the child's parents or the den mother."},{"type":"Storm Rider","kind":"Su","details":"A storm hag is considered two size categories larger than she actually is in regard to wind effects."},{"type":"Storm Strike","kind":"Su","details":"Each time a storm hag makes a successful attack with her bite, claws, or when she uses a weapon that is predominantly made of metal the attack deals an additional 1d6 points of electricity damage."},{"type":"Whipping Winds","kind":"Su","details":"As a standard action, a storm hag can use her gust of wind spell-like ability to trip her foes. This ability can only affect one target within 30 ft., and the storm hag uses her combat maneuver bonus as if tripping a creature normally. The gust of wind spell doesn't possess its normal effects, but instead sweeps a creature off its ft. Attempting to trip a creature with this ability doesn't provoke an attack of opportunity, but casting the spell-like ability provokes attacks of opportunity as normal."}],"description":"When the clouds turn gray and the winds pick up into a howl, wise travelers pray that the cause is only a natural tempest and the foul weather isn't connected with a storm hag. Storm hags are hateful creatures, and strangely, their hate is one of the few things that brings them pleasure.\n\nA storm hag resembles a shrunken old woman with a thundercloud of hair stacked atop her wrinkled head. Her mouth hangs open, revealing thin pointed teeth; small arcs of electricity can be seen jumping across her teeth and spittle. Black talons sprout from her fingertips, likewise crackling with electricity. A storm hag's wrinkled face contains a look of gleeful distaste, and her eyes are thick with cataracts, rendering her gaze pupil-less. A storm hag's hair is wild and unruly with static electricity popping and crackling throughout the mass. Seemingly animated, a storm hag's hair can easily stand as tall as she is. Wiry and stooped, a storm hag weighs about 70 pounds and stands a little over 4 ft. tall, though if she stood up straight she could easily reach 5 ft. or more. A storm hag usually wears rough furs and coarse woolen clothing that is rarely cleaned, giving her a distinctly unpleasant odor.\n\nEcology\n\nLike most other living things, a storm hag needs to eat, and her favorite meal is the tender flesh of young children. Storm hags use their ability to smell children and young animals to track down their meals no matter where the child has hidden himself. On Golarion, storm hags have developed a special fondness for Kellid and Ulfen children.\n\nStorm hags find the childlike gnomes and half lings infuriating. It is unknown why this is so-perhaps storm hags cannot distinguish between children and members of these small races on sight and are angered that their prey isn't actually their favorite food. They may very well just have some other unknown pet peeve about the smaller folk, but either way, the presence of gnomes or half lings drives storm hags into a rage. When given the choice, storm hags always target members of these races above all others.\n\nHabitat & Society\n\nStorm hags are most numerous in the northern lands of the Inner Sea region, but with their ability to fly, their insatiable hunger, and the desire to share their hate with others, storm hags can likely appear anywhere. They prefer areas that are prone to inclement weather, and enjoy flying through the air during thunderstorms, feeling the static discharge dancing across their warty skin. Storm hags most frequently claim territory in the wild spaces between settlements where they keep their distance from civilization unless hunting. Like a predator, a storm hag constantly surveys her territory and takes great pains in keeping a secret den she considers always hers. For the most part, a storm hag is content to remain in one place if the food is plentiful and her shelter is safe and obscured. A storm hag's den is a simple, yet grotesque affair, often located in deep, dark forests or atop craggy mountains, and is always hidden from sight. Cluttered with bones and skins from previous meals, a den's most dominant feature is the storm hag's cauldron.\n\nStorm hags roam their territory hunting, preferring to prey on children if possible, but they do consider adult humanoids suitable substitutes when children are unavailable. A storm hag only stoops to eating animals when her hunger grows too strong, however.\n\nWhen a storm hag encounters travelers in her territory, she torments the unwitting visitors, calling down the winds and whipping up a storm of howling gales and crashing lightning to break her enemies' ranks and to send them running for shelter. Once her prey has been cornered into a cave or thicket where they sought shelter from the weather, the storm hag sows discontent by using her whispering wind spell-like ability to harass and frighten the sheltered travelers with a hate-filled, disembodied voice. Like a cat toying with a crippled field mouse, the storm hag pushes her prey to their breaking point-letting them steep in shivering fright-before confronting them face to face with tooth, claw, and lightning before finally killing and consuming them.\n\nStorm Hag Covens\n\nLike other hags, storm hags form covens. They prefer to form these covens with other storm hags, but storm hags have been known to team up with green hags or other hags on occasion. Storm hags inhabiting stormy coasts or soggy salt marshes sometimes ally with sea hags and form covens with them. Though they respect the strength of annis hags, few storm hags enter into a coven with those brutish and simple creatures. When they do, the storm hags rely on the annis hags' intimidating physical might to help in their hunts.\n\nA storm hag is an attractive prospect for any burgeoning coven-to-be, but these hags aren't easily wooed into joining with others. A storm hag is haughty and views her way of doing something as the best, if only because she is the one doing it. Any hag thinking of forming a coven with a storm hag would do well to ride a fine line between flattery and outright dominance by performing simultaneous acts of humble depravity and honorific evil. The other two hags in a coven with a storm hag gain her child-scent ability as long as they are within 100 ft. of the storm hag. In addition, a coven with a storm hag as a member has access to the following spell-like abilities beyond what a normal coven provides: call lightning storm (DC 18), plague storm (DC 19), quench (DC 16), whirlwind (DC 21), wind wall. Like other covens, all three hags must be within 10 ft. of one another and must work together and take a full-round action take part in this cooperative magic.","ecology":"Like most other living things, a storm hag needs to eat, and her favorite meal is the tender flesh of young children. Storm hags use their ability to smell children and young animals to track down their meals no matter where the child has hidden himself. On Golarion, storm hags have developed a special fondness for Kellid and Ulfen children.\n\nStorm hags find the childlike gnomes and half lings infuriating. It is unknown why this is so-perhaps storm hags cannot distinguish between children and members of these small races on sight and are angered that their prey isn't actually their favorite food. They may very well just have some other unknown pet peeve about the smaller folk, but either way, the presence of gnomes or half lings drives storm hags into a rage. When given the choice, storm hags always target members of these races above all others.","habitat_society":"Storm hags are most numerous in the northern lands of the Inner Sea region, but with their ability to fly, their insatiable hunger, and the desire to share their hate with others, storm hags can likely appear anywhere. They prefer areas that are prone to inclement weather, and enjoy flying through the air during thunderstorms, feeling the static discharge dancing across their warty skin. Storm hags most frequently claim territory in the wild spaces between settlements where they keep their distance from civilization unless hunting. Like a predator, a storm hag constantly surveys her territory and takes great pains in keeping a secret den she considers always hers. For the most part, a storm hag is content to remain in one place if the food is plentiful and her shelter is safe and obscured. A storm hag's den is a simple, yet grotesque affair, often located in deep, dark forests or atop craggy mountains, and is always hidden from sight. Cluttered with bones and skins from previous meals, a den's most dominant feature is the storm hag's cauldron.\n\nStorm hags roam their territory hunting, preferring to prey on children if possible, but they do consider adult humanoids suitable substitutes when children are unavailable. A storm hag only stoops to eating animals when her hunger grows too strong, however.\n\nWhen a storm hag encounters travelers in her territory, she torments the unwitting visitors, calling down the winds and whipping up a storm of howling gales and crashing lightning to break her enemies' ranks and to send them running for shelter. Once her prey has been cornered into a cave or thicket where they sought shelter from the weather, the storm hag sows discontent by using her whispering wind spell-like ability to harass and frighten the sheltered travelers with a hate-filled, disembodied voice. Like a cat toying with a crippled field mouse, the storm hag pushes her prey to their breaking point-letting them steep in shivering fright-before confronting them face to face with tooth, claw, and lightning before finally killing and consuming them.\n\nStorm Hag Covens\n\nLike other hags, storm hags form covens. They prefer to form these covens with other storm hags, but storm hags have been known to team up with green hags or other hags on occasion. Storm hags inhabiting stormy coasts or soggy salt marshes sometimes ally with sea hags and form covens with them. Though they respect the strength of annis hags, few storm hags enter into a coven with those brutish and simple creatures. When they do, the storm hags rely on the annis hags' intimidating physical might to help in their hunts.\n\nA storm hag is an attractive prospect for any burgeoning coven-to-be, but these hags aren't easily wooed into joining with others. A storm hag is haughty and views her way of doing something as the best, if only because she is the one doing it. Any hag thinking of forming a coven with a storm hag would do well to ride a fine line between flattery and outright dominance by performing simultaneous acts of humble depravity and honorific evil. The other two hags in a coven with a storm hag gain her child-scent ability as long as they are within 100 ft. of the storm hag. In addition, a coven with a storm hag as a member has access to the following spell-like abilities beyond what a normal coven provides: call lightning storm (DC 18), plague storm (DC 19), quench (DC 16), whirlwind (DC 21), wind wall. Like other covens, all three hags must be within 10 ft. of one another and must work together and take a full-round action take part in this cooperative magic."},{"name":"Stygira","cr":7,"xp":3200,"alignment":"LE","size":"Medium","type":"monstrous humanoid","init":7,"senses":[{"type":"blindsight 30 ft.","modifier":"120 ft. with gem eye"},{"type":"scent"},{"type":"true seeing with gem eye"}],"ac":19,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+3 Dex, +6 natural","hp":76,"hd":"8d10+32","hdvalue":8,"fort":6,"ref":9,"will":14,"dr":"10/adamantine","immunities":["gaze attacks","paralysis","petrification"],"sr":18,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +11 (1d4+3 plus stone curse)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"gem gaze"},{"type":"stone curse"}],"strength":17,"dexterity":16,"constitution":18,"intelligence":17,"wisdom":22,"charisma":15,"baseatk":8,"cmb":11,"cmd":24,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Improved Initiative"},{"feat":"Iron Will"}],"skills":[{"skill":"Bluff","value":10},{"skill":"Knowledge (arcana)","value":11},{"skill":"Knowledge (dungeoneering)","value":11},{"skill":"Knowledge (religion)","value":11},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":16},{"skill":"Spellcraft","value":11}],"languages":["Cyclops","Giant","Terran"],"sq":[{"type":"gem eye"}],"environments":["temperate hills","temperate underground"],"organizations":["solitary","pair","mystery (3-7)"],"treasure":"standard (typically gemstones)","description_visual":"Gaunt and parched, this crone-like figure moves with the predatory jerkiness of a hunting vulture. Unnaturally tall and lean, her form is all cracked flesh and stony crevices spanning a wasteland of withered gray flesh. Shattered black teeth jut from a chapped, lipless mouth that stretches beneath a high, scarred brow devoid of nose or eyes.","source":"AP 33","special_abilities":[{"type":"Gem Eye","kind":"Su","details":"Stygiras possess a special connection with gemstones. While holding or otherwise in contact with a gemstone of at least the size of a human eye, a stygira can see through the gemstone like a magical eye, viewing her surroundings as if her blindsense extended to 120 ft. and she were under the effects of true seeing, which grants her a +4 bonus on Perception checks."},{"type":"Gem Gaze","kind":"Su","details":"Shaken for 1d4 rounds, 30 ft., Fortitude DC 16 negates. The save DC is Charisma-based. A stygira can only make use of this ability while holding a gemstone. Light Blindness Despite their effective blindness, stygiras remain sensitive to light. Abrupt exposure to bright light blinds stygiras for 1 round; on subsequent rounds, they are dazzled as long as they remain in the affected area."},{"type":"Stone Curse","kind":"Su","details":"Any creature struck by a stygira's claws must make a DC 18 Will save or be affected by a curse that gradually drains it of color, stiffens its joints, and finally turns the victim to stone. This curse proves frighteningly unpredictable, forcing another save against its effects every 1d3 hours. Any creature that is drained to 0 Dexterity or fails three saves against the curse is permanently petrified. Even if a creature is petrified and then restored to flesh, it is still affected by the curse and is petrified again upon failing its next save against the curse. A stone curse can only be removed in one of two ways: by casting remove curse or by spending a full hour in unobstructed natural sunlight. Magical radiance like daylight doesn't affect a stone curse, and remove curse doesn't return a petrified creature to flesh. The save DC is Constitution-based. Stone curse: Claw-curse; save Will DC 18; frequency 1/1d3 hours; effect 1d6 Dex damage, failing 3 saves results in petrification; cure casting remove curse or spending 1 hour in natural sunlight."}],"description":"Withered hermits wrapped in tattered black rags, these scarred, eyeless crones slip through the dark crevasses of both earth and time. Degenerate inheritors of the half-remembered, collapsed cyclops civilizations, the stygiras-or stone witches, as they are often called- command strange secrets of the earth and interpret the fateful energies of the depths. Ages of communion with the darkness and reliance upon alien magics have corrupted the stygiras from the primitive human witches their ancestors were countless ages ago, transforming them into a terrifying, debased breed infused with magics not their own. In many a savage land, these crones were once or are still worshiped as seers and demigods, weaving magic and communing with the earth to manipulate their servants into obeying their selfish and grotesque whims. In other realms, they haunt the night, prowling from their caves to feed upon the unwary or make alliances with those cruel and ambitious enough to believe their perverse counsel. Yet for all their perverse blasphemies and primitive desires, their powers to see what none should and reduce life to brittle stone proves enough to inspire dread and superstitious belief in nearly all who hear of the harsh stone witches. Stygiras on average stand 6-1/2 ft. tall and weigh approximately 150 pounds. Ecology It is said that the stygiras draw their power from stone and from the darkness. Certainly they live their entire lives in the dark, traveling through intricate, maze-like caverns and the moonless sky with equal ease. They draw their sustenance from the base things they scrape from the earth-vermin, molds, lichens, and whatever fleshy things happen into their lairs. Although technically blind, stygiras have almost supernaturally keen hearing, taste, and touch, and so have no need for sight. What remains of the eyes that lurk as vestigial elements of their anatomy hide beneath the scarred flesh of their faces. While such remnant organs typically go unused, they can still detect the presence of light, an uncomfortable sensation that all stygiras take great pains to avoid. Stygiras can in fact travel under the skies, but they quickly become agoraphobic and retreat to the safety of shadowy canyons or caves as soon as possible. They avoid the sunlight hours, with most willing to face death in the darkness rather than take their chances venturing into the light. All stygiras are female; they are capable of reproducing with humanoids of nearly any species and always bearing three or more withered-and typically stillborn-stygira young. Yet stygiras make up for their appallingly low live birth and survival rates with unnaturally long lifespans. None can say how long stygiras who don't meet their end by violence might live, but instances of stone witches living for 3 or more centuries are well documented. Habitat & Society Stygiras most commonly occupy lands near the phenomenally ancient tombs and monuments of the cyclops empires. While some of the crazed witches make the impossible claim that all stygira are the surviving mortal apprentices of primordial cyclops seers, saner minds posit that the predecessors of these crones were primitive human shamans and mystics who managed to tap into a degree of the fallen empires' powers. Whatever the case, the connection between stygiras and the ancient cyclopes lingers in their shared language and the mad scrawls covering many of these hags' lairs.","ecology":"It is said that the stygiras draw their power from stone and from the darkness. Certainly they live their entire lives in the dark, traveling through intricate, maze-like caverns and the moonless sky with equal ease. They draw their sustenance from the base things they scrape from the earth-vermin, molds, lichens, and whatever fleshy things happen into their lairs. Although technically blind, stygiras have almost supernaturally keen hearing, taste, and touch, and so have no need for sight. What remains of the eyes that lurk as vestigial elements of their anatomy hide beneath the scarred flesh of their faces. While such remnant organs typically go unused, they can still detect the presence of light, an uncomfortable sensation that all stygiras take great pains to avoid. Stygiras can in fact travel under the skies, but they quickly become agoraphobic and retreat to the safety of shadowy canyons or caves as soon as possible. They avoid the sunlight hours, with most willing to face death in the darkness rather than take their chances venturing into the light. All stygiras are female; they are capable of reproducing with humanoids of nearly any species and always bearing three or more withered-and typically stillborn-stygira young. Yet stygiras make up for their appallingly low live birth and survival rates with unnaturally long lifespans. None can say how long stygiras who don't meet their end by violence might live, but instances of stone witches living for 3 or more centuries are well documented.","habitat_society":"Stygiras most commonly occupy lands near the phenomenally ancient tombs and monuments of the cyclops empires. While some of the crazed witches make the impossible claim that all stygira are the surviving mortal apprentices of primordial cyclops seers, saner minds posit that the predecessors of these crones were primitive human shamans and mystics who managed to tap into a degree of the fallen empires' powers. Whatever the case, the connection between stygiras and the ancient cyclopes lingers in their shared language and the mad scrawls covering many of these hags' lairs."},{"name":"Succubus","cr":7,"xp":3200,"alignment":"CE","size":"Medium","type":"outsider","subtypes":["chaotic","demon","evil","extraplanar"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"}],"ac":20,"ac_touch":13,"ac_flat_footed":17,"ac_mods":"+3 Dex, +7 natural","hp":84,"hd":"8d10+40","hdvalue":8,"fort":7,"ref":9,"will":10,"dr":"10/cold iron or good","immunities":["electricity","fire","poison"],"resists":[{"type":"acid","value":10},{"type":"cold","value":10}],"sr":18,"speed":[{"type":"land","speed":30},{"type":"fly","speed":50,"maneuverability":"average"}],"melee":"2 claws +11 (1d6+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"energy drain"},{"type":"profane gift"}],"spell_like_abilities_caster_level":12,"spell_like_abilities_concentration":17,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"tongues"}]},{"frequency":"at-will","spells":[{"spell":"charm monster"},{"spell":"detect thoughts"},{"spell":"ethereal jaunt","details":"self plus 50 lbs. of objects only"},{"spell":"greater teleport","details":"self plus 50 lbs. of objects only"},{"spell":"suggestion"},{"spell":"vampiric touch"}]},{"frequency":"1/day","spells":[{"spell":"dominate person"},{"spell":"summon","details":"level 3, 1 babau 50%"}]}],"strength":13,"dexterity":17,"constitution":20,"intelligence":18,"wisdom":14,"charisma":27,"baseatk":8,"cmb":11,"cmd":22,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Iron Will"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":27},{"skill":"Diplomacy","value":19},{"skill":"Disguise","value":19},{"skill":"Escape Artist","value":11},{"skill":"Fly","value":14},{"skill":"Intimidate","value":16},{"skill":"Knowledge (local)","value":15},{"skill":"Perception","value":21},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":14}],"languages":["Abyssal","Celestial","Common","Draconic","tongues","telepathy 100 ft."],"sq":[{"type":"change shape","details":"alter self, Small or Medium humanoid"}],"environments":["any (Abyss)"],"organizations":["solitary","pair","harem (3-12)"],"treasure":"double","description_visual":"Tiny horns, bat-like wings, and a sinuous tail betray the demonic nature of this alluring woman.","group":"Demon","source":"PFRPG Bestiary","special_abilities":[{"type":"Energy Drain","kind":"Su","details":"A succubus drains energy from a mortal she lures into an act of passion, such as a kiss. An unwilling victim must be grappled before the succubus can use this ability. The succubus's kiss bestows one negative level. The kiss also has the effect of a suggestion spell, asking the victim to accept another act of passion from the succubus. The victim must succeed on a DC 22 Will save to negate the suggestion. The DC is 22 for the Fortitude save to remove a negative level. These save DCs are Charisma-based."},{"type":"Profane Gift","kind":"Su","details":"Once per day as a full-round action, a succubus may grant a profane gift to a willing humanoid creature by touching it for 1 full round. The target gains a +2 profane bonus to an ability score of his choice. A single creature may have no more than one profane gift from a succubus at a time. As long as the profane gift persists, the succubus can communicate telepathically with the target across any distance (and may use her suggestion spell-like ability through it). A profane gift is removed by dispel evil or dispel chaos. The succubus can remove it as well as a free action (causing 2d6 Charisma drain to the victim, no save)."}],"description":"Among the demon hordes, a succubus can often rise to incredible heights of power through her manipulations and sensual charms, and many a demonic war has raged due to the subtle machinations of such creatures. A succubus is formed from the souls of particularly lustful and rapacious evil mortals.","ecology":"","habitat_society":""},{"name":"Suspiridaemon","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["thin air"],"ac":20,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+3 Dex, +1 dodge, +6 natural","hp":85,"hd":"9d10+36","hdvalue":9,"fort":9,"ref":9,"will":8,"dr":"10/good or silver","immunities":["acid","disease","death effects","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10},{"type":"sonic","value":30}],"sr":18,"speed":[{"type":"land","speed":30}],"melee":"2 claws +13 (1d4+4), tongue +8 (1d6+6/19-20 plus grab)","space":"5 ft.","reach":"5 ft. (10 ft. with tongue)","special_attacks":[{"type":"concussive gasp"},{"type":"constrict","details":"1d6+6"},{"type":"strangle"},{"type":"suffocate"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":13,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"death knell"},{"spell":"ghoul touch"},{"spell":"ray of enfeeblement"}]},{"frequency":"1/day","spells":[{"spell":"cloudkill"},{"spell":"summon","details":"level 4, 1d3 lacridaemons 35%"}]},{"frequency":"3/day","spells":[{"spell":"stinking cloud"},{"spell":"vampiric touch"}]}],"strength":19,"dexterity":17,"constitution":18,"intelligence":14,"wisdom":15,"charisma":18,"baseatk":9,"cmb":13,"cmb_special":"+4 vs. grapple","cmd":27,"feats":[{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Critical (tongue)"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Climb","value":16},{"skill":"Diplomacy","value":16},{"skill":"Intimidate","value":16},{"skill":"Knowledge (nature)","value":14},{"skill":"Knowledge (planes)","value":14},{"skill":"Perception","value":14},{"skill":"Sense Motive","value":14},{"skill":"Stealth","value":15}],"languages":["Abyssal","Draconic","Infernal (cannot speak)","telepathy 100 ft."],"sq":[{"type":"no breath"}],"environments":["any (Abaddon)"],"organizations":["solitary","gang (2-4)","mob (5-9)"],"treasure":"standard","description_visual":"This tall, three-legged fiend possesses an avian body and head, save for its gangly arms, which end in thin, clawlike fingers. Its scrawny neck is adorned with three thick iron rings, and a grotesquely long, barbed tongue resembling an octopus's tentacle winds out of its oversized beak. Burst blood vessels fill the creature's wide eyes, and reddish speckled blotches cover its cyanotic flesh.","source":"Horsemen Of The Apocalypse","special_abilities":[{"type":"Concussive Gasp","kind":"Su","details":"Once per day, a suspiridaemon can inhale with such sudden force as to evacuate the air in its proximity, causing a sudden wave of air pressure from the implosion. Every creature within 30 ft. must make a DC 18 Fortitude save or take 5d6 points of sonic damage and become sickened for 1d4 rounds. Any creature that makes a successful save takes only half damage and isn't sickened. A suspiridaemon cannot perform this ability if it is currently grappling a creature with its tongue. The save DC is Constitution-based."},{"type":"Strangle","kind":"Ex","details":"Suspiridaemons have an unerring talent for seizing their victims by the neck. A creature that is grappled by a suspiridaemon cannot speak or cast spells with verbal components."},{"type":"Suffocate","kind":"Ex","details":"A creature affected by the daemon's strangle ability cannot breathe and must hold its breath. Because of the daemon's thin air aura, this can quickly render an opponent unconscious."},{"type":"Thin Air","kind":"Su","details":"A suspiridaemon's aura makes the air around it difficult to breathe. Creatures that need to breathe can only hold their breath half as long as normal while within this aura, and suffer from altitude sickness as if in a low peak or high pass (see Altitude Zones)."}],"description":"Horrid fiends whose very presence makes the air difficult to breathe, suspiridaemons personify death by suffocation. Discolored and blotched like the stagnant blood of a suffocated corpse, a suspiridaemon enjoys nothing more than the last choked gasp of a victim as it wraps its tongue around the creature's throat. While a suspiridaemon doesn't normally breathe, its body is nonetheless convulsive and twitchy; coupled with its utterly silent demeanor, they excel at slow, gruesome kills while hiding in the shadows. The only time a suspiridaemon makes a noticeable noise is when it suddenly loosens the binds around its neck and inhales a booming breath, the sudden loss of air enough to make foes fall ill.\n\nEcology\n\nA suspiridaemon arises from an evil soul that died by suffocation, drowning, or execution by hanging. Each individual suspiridaemon bears the mark of its particular manner of mortal death-usually in the form of the bruised or mangled flesh of its throat-and the large iron collars around its neck hide such shameful reminders of life, though the suspiridaemon itself is often unaware of this. A suspiridaemon comes into being with the rings already bound around its throat, so that it never witnesses the aff lictions that sent it to Abaddon in the first place. It is thought that should the collars around a suspiridaemon's throat ever be broken, the fiend's head would crook clumsily downward, allowing the monster to see wounds that might remind it of the terrible death it endured in its past existence.\n\nSuspiridaemons pride themselves on the number of souls they have deprived of life by strangulation, and this amount often corresponds to the number of iron rings a suspiridaemon wears on its body. While most suspiridaemons are relatively weak compared to their daemonic kin, a particularly skillful individual who is talented at crafting as well as killing can construct iron collars adorned with gem slots, items that give the suspiridaemon the ability to contain the souls of its victims in the rings for trade in the soul markets of Abaddon. When a suspiridaemon is slain, its iron rings disintegrate into ash, and any gems held within are shattered as well, freeing the trapped souls.\n\nA suspiridaemon generally uses stealth when confronting foes. Unleashing its long, winding tongue from a dark corner, one of these fiends will strangle an unwary foe in isolation from the rest of the creature's party. When in combat, a suspiridaemon greatly prefers to kill its enemies by its own hands or its barbed tongue, using its arcane abilities and other daemonic gifts to wear down or sow discord into a group of opponents. To a suspiridaemon, there is no act more appreciable than choking the life from a victim, and bringing the creature close to hear its final, distorted gasp.\n\nA suspiridaemon prefers to take souls from creatures who are on the verge of death, but aren't quite there yet; the fiend gazes at its victim's expiring face, drawing the dying creature's soul out of it with a solemn suspension of the daemon's normal twitching and convulsing. Those who have witnessed a suspiridaemon draw the life from a creature claim that the fiend almost seems to be inhaling fresh air for the first time as the victim's physical shell expires, and for the briefest moment, the monster appears to breathe normally. The eerie spectacle ends as quickly as it begins, however, as the suspiridaemon sets its gaze upon its next victim, preparing its vicious tongue for another attack.\n\nHabitat & Society\n\nWhile many daemons dedicate their loyalty to one of the Horsemen or some other power within Abaddon, either based on their origins, historical ties, or environmental circumstances, no such proclivities exist for suspiridaemons. Suspiridaemons avoid operating under masters whenever possible, preferring more individualistic careers of murder and destruction. They tend to work well with other daemons when forced into doing so, though the more daring individuals tend to stray from Abaddon and gravitate toward population centers on other planes to stalk prey as they please. Suspiridaemons traversing the multiverse in a pack regularly take their small hunting parties into the wilderness around smaller settlements, ravenous in their pursuit of those who stray from the protective gazes of allies. While their killing tactics are as ruthless as any other daemon, suspiridaemons' murders are particularly shrouded in a cold manner of sincere and solemn contemplation, their grisly crimes against souls veiled in a mist of contempt toward the living as well as hatred for themselves. Some speculate that this self-hatred might be connected to the lingering doubts as to their origins, the itch beneath their iron collars that reminds them of their own past mortality. Whatever the cause of their self-doubt, the feeling doesn't seem to bother most other daemons, who generally view suspiridaemons as useful companions whether inside or outside of Abaddon. Piscodaemons and sangudaemons in particular consider them among the most ideal lesser daemons to command.\n\nSuspiridaemons cannot speak, and rarely use their powers of telepathy to communicate, simply nodding discreetly when given a task by a more powerful daemon. This silent subservience only adds to other daemons' general appreciation of their humble and disturbing demeanors, though most are sure to keep the strangling fiends at a distance.","ecology":"A suspiridaemon arises from an evil soul that died by suffocation, drowning, or execution by hanging. Each individual suspiridaemon bears the mark of its particular manner of mortal death-usually in the form of the bruised or mangled flesh of its throat-and the large iron collars around its neck hide such shameful reminders of life, though the suspiridaemon itself is often unaware of this. A suspiridaemon comes into being with the rings already bound around its throat, so that it never witnesses the aff lictions that sent it to Abaddon in the first place. It is thought that should the collars around a suspiridaemon's throat ever be broken, the fiend's head would crook clumsily downward, allowing the monster to see wounds that might remind it of the terrible death it endured in its past existence.\n\nSuspiridaemons pride themselves on the number of souls they have deprived of life by strangulation, and this amount often corresponds to the number of iron rings a suspiridaemon wears on its body. While most suspiridaemons are relatively weak compared to their daemonic kin, a particularly skillful individual who is talented at crafting as well as killing can construct iron collars adorned with gem slots, items that give the suspiridaemon the ability to contain the souls of its victims in the rings for trade in the soul markets of Abaddon. When a suspiridaemon is slain, its iron rings disintegrate into ash, and any gems held within are shattered as well, freeing the trapped souls.\n\nA suspiridaemon generally uses stealth when confronting foes. Unleashing its long, winding tongue from a dark corner, one of these fiends will strangle an unwary foe in isolation from the rest of the creature's party. When in combat, a suspiridaemon greatly prefers to kill its enemies by its own hands or its barbed tongue, using its arcane abilities and other daemonic gifts to wear down or sow discord into a group of opponents. To a suspiridaemon, there is no act more appreciable than choking the life from a victim, and bringing the creature close to hear its final, distorted gasp.\n\nA suspiridaemon prefers to take souls from creatures who are on the verge of death, but aren't quite there yet; the fiend gazes at its victim's expiring face, drawing the dying creature's soul out of it with a solemn suspension of the daemon's normal twitching and convulsing. Those who have witnessed a suspiridaemon draw the life from a creature claim that the fiend almost seems to be inhaling fresh air for the first time as the victim's physical shell expires, and for the briefest moment, the monster appears to breathe normally. The eerie spectacle ends as quickly as it begins, however, as the suspiridaemon sets its gaze upon its next victim, preparing its vicious tongue for another attack.","habitat_society":"While many daemons dedicate their loyalty to one of the Horsemen or some other power within Abaddon, either based on their origins, historical ties, or environmental circumstances, no such proclivities exist for suspiridaemons. Suspiridaemons avoid operating under masters whenever possible, preferring more individualistic careers of murder and destruction. They tend to work well with other daemons when forced into doing so, though the more daring individuals tend to stray from Abaddon and gravitate toward population centers on other planes to stalk prey as they please. Suspiridaemons traversing the multiverse in a pack regularly take their small hunting parties into the wilderness around smaller settlements, ravenous in their pursuit of those who stray from the protective gazes of allies. While their killing tactics are as ruthless as any other daemon, suspiridaemons' murders are particularly shrouded in a cold manner of sincere and solemn contemplation, their grisly crimes against souls veiled in a mist of contempt toward the living as well as hatred for themselves. Some speculate that this self-hatred might be connected to the lingering doubts as to their origins, the itch beneath their iron collars that reminds them of their own past mortality. Whatever the cause of their self-doubt, the feeling doesn't seem to bother most other daemons, who generally view suspiridaemons as useful companions whether inside or outside of Abaddon. Piscodaemons and sangudaemons in particular consider them among the most ideal lesser daemons to command.\n\nSuspiridaemons cannot speak, and rarely use their powers of telepathy to communicate, simply nodding discreetly when given a task by a more powerful daemon. This silent subservience only adds to other daemons' general appreciation of their humble and disturbing demeanors, though most are sure to keep the strangling fiends at a distance."},{"name":"Theletos","cr":7,"xp":3200,"alignment":"N","size":"Medium","type":"outsider","subtypes":["aeon","extraplanar"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":15,"ac_flat_footed":17,"ac_mods":"+2 deflection, +2 Dex, +1 dodge, +5 natural","hp":76,"hd":"9d10+27","hdvalue":9,"hp_mods":["fast healing 5"],"fort":9,"ref":5,"will":7,"immunities":["cold","critical hits","poison"],"resists":[{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":18,"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"poor"}],"melee":"2 slams +13 (1d6+4), 2 tentacles +8 (1d4+2 plus fate drain)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"wreath of fate"}],"spell_like_abilities_caster_level":9,"spell_like_abilities_concentration":12,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"augury"},{"spell":"command"},{"spell":"doom"},{"spell":"sanctuary"}]},{"frequency":"1/day","spells":[{"spell":"charm monster"},{"spell":"lesser geas"}]},{"frequency":"3/day","spells":[{"spell":"bestow curse"},{"spell":"dispel magic"},{"spell":"enthrall"},{"spell":"remove curse"},{"spell":"suggestion"},{"spell":"touch of idiocy"}]}],"strength":18,"dexterity":14,"constitution":17,"intelligence":11,"wisdom":19,"charisma":12,"baseatk":9,"cmb":7,"cmd":21,"feats":[{"feat":"Dodge"},{"feat":"Hover"},{"feat":"Improved Initiative"},{"feat":"Improved Iron Will"},{"feat":"Iron Will"}],"skills":[{"skill":"Fly","value":-2},{"skill":"Intimidate","value":13},{"skill":"Knowledge (planes)","value":16},{"skill":"Perception","value":16},{"skill":"Sense Motive","value":16},{"skill":"Spellcraft","value":12},{"skill":"Stealth","value":14}],"languages":["envisaging"],"sq":[{"type":"extension of all"},{"type":"void form"}],"environments":["any (Outer Planes)"],"organizations":["solitary","pair","collective (3-12)"],"treasure":"none","description_visual":"Four bandy limbs, each splitting at the elbow into two threefingered forearms, emerge from this creature's crystalline body.","group":"Aeon","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Fate Drain","kind":"Su","details":"A theletos possesses a pair of flexible crystalline tentacles with which it can drain a creature's sense of fate and destiny. Whenever it strikes a foe with these tentacles, the creature struck must make a DC 17 Will save or take 1d4 points of Charisma damage. Until a creature's Charisma damage from this ability is healed, the victim takes a -2 penalty on all saving throws (regardless of the actual total amount of Charisma damage it takes). The save DC is Constitution-based."},{"type":"Wreath of Fate","kind":"Su","details":"As a full-round-action every 1d4 rounds, a theletos can release a 60-foot cone of energy from its chest. Any intelligent creature struck by this cone must make a DC 15 Will save or become nearly overwhelmed with the knowledge of various fates that destiny has in store for him-there is no way to make sense of these myriad dooms and boons, and as a result, the victim is staggered. As long as this condition persists, the victim may choose to make two rolls when attempting an attack roll, a saving throw, or a skill check-he must accept the worse of the two rolls, but in so doing the wreath of fate passes from his soul and he is no longer staggered by this ability. Wreath of fate is a curse effect, and as such can be affected by remove curse or break enchantment-the effective caster level of this curse is equal to the theletos's HD (CL 9th in most cases). The save DC is Charisma-based."}],"description":"The strange theletos is the guardian of the duality between freedom and fate. Slavery is no more of an issue to a theletos than is true freedom, but without one, the other cannot exist. In areas where slavery is rife, a theletos might aid in freeing some slaves, while in regions where slavery has been abolished, this strange being works to subjugate many creatures with its own mind-controlling spell-like abilities-often encouraging them to further undertake acts of slavery themselves. The theletos is also a guardian of fate and prophecy, and while for some creatures it might allow glimpses of futures, others who peer into the future almost seem to cause the aeon physical pain. The theletos cannot explain why one seer might be allowed to divine futures while another should not-it knows only that some prophets should be denied this pursuit.\n\nA theletos is 5 ft. tall and weighs 100 pounds.","ecology":"","habitat_society":""},{"name":"Totenmaske","cr":7,"xp":3200,"alignment":"NE","size":"Medium","type":"undead","subtypes":["shapechanger"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+6 Dex, +4 natural","hp":85,"hd":"10d8+40","hdvalue":10,"fort":7,"ref":9,"will":2,"immunities":["undead traits"],"resists":[{"type":"cold","value":20}],"speed":[{"type":"land","speed":50}],"melee":"bite +13 (1d8+4 plus 1d4 Cha drain), 2 claws +13 (1d6+4)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"fleshdrink"},{"type":"shape flesh"}],"strength":18,"dexterity":23,"intelligence":16,"wisdom":15,"charisma":19,"baseatk":7,"cmb":10,"cmd":21,"feats":[{"feat":"Ability Focus (Charisma drain)"},{"feat":"Combat Expertise"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":16,"special":"+24 jump"},{"skill":"Bluff","value":14},{"skill":"Diplomacy","value":14},{"skill":"Disguise","value":17},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":19}],"languages":["Abyssal","Celestial","Common","Infernal"],"sq":[{"type":"change shape","details":"the previous humanoid it successfully used its fleshdrink ability on; alter self"}],"environments":["any land","any underground"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This spindly, skeletal humanoid has moldy green flesh, long talons for hands, and a head that seems to be mostly mouth.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Charisma Drain","kind":"Su","details":"A totenmaske can eat the hopes and dreams of a creature it bites, dealing 1d4 points of Charisma drain unless the victim makes a DC 21 Will save. The save DC is Charisma-based."},{"type":"Fleshdrink","kind":"Su","details":"If a totenmaske hits a single creature with both claw attacks, the hollow claws drain away some of the target's flesh, dealing 1d6 points of Constitution damage and making the victim sickened for 1d4 rounds. A successful DC 19 Fortitude save negates the Constitution damage and reduces the sickened condition duration to 1 round. The save DC is Charisma-based."},{"type":"Shape Flesh","kind":"Su","details":"By spending 1 minute in contact with a helpless creature, a totenmaske can reshape the target's face, causing flesh to cover vital features. The target may attempt a DC 19 Fortitude save to resist. Changes are permanent, but can be reversed with heal, restoration, or regeneration, or by surgically opening the sealed flesh with a DC 15 Heal check that takes 1d3 rounds and deals 1d4 points of damage even if the check isn't successful. A totenmaske can use this ability on one of four different features per use: ears (target becomes deaf), eyes (target becomes blind), mouth (target cannot speak or eat), or nose (target cannot smell). Multiple uses can have increasingly serious effects (such as sealing the mouth and nose, which causes suffocation). The save DC is Charisma-based."}],"description":"Consumed by the same lusts and excesses that led them in life, the souls of some sinners rise as totenmaskes, drinking the flesh and memories of living creatures and even stepping into their lives to once more pursue their base desires. Incapable of resuming their sinful pursuits in their natural form, totenmaskes often keep their victims alive for as long as possible, renewing their stolen identities regularly in order to continue indulging in pleasures of the flesh.\n\nA totenmaske can be created from the corpse of a sinful mortal by a cleric of at least 18th level using the create greater undead spell.\n\nA totenmaske is 6 ft. tall and weighs 140 pounds.","ecology":"","habitat_society":""},{"name":"Tupilaq","cr":7,"xp":3200,"alignment":"N","size":"Small","type":"construct","init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":15,"ac_flat_footed":16,"ac_mods":"+4 Dex, +5 natural, +1 size","hp":59,"hd":"9d10+10","hdvalue":9,"fort":3,"ref":7,"will":3,"dr":"10/bludgeoning","immunities":["construct traits"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"bite +15 (1d8+10/19-20 plus grab), 2 claws +15 (1d4+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"seek target"},{"type":"shearing jaws"}],"spell_like_abilities_caster_level":7,"spell_like_abilities_concentration":7,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"invisibility"}]}],"strength":21,"dexterity":18,"wisdom":11,"charisma":5,"baseatk":9,"cmb":13,"cmb_special":"+4 vs. grapple","cmd":27,"skills":[{"skill":"Swim","value":13}],"sq":[{"type":"scrimshaw magic"}],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This small humanoid figure grinds and clatters as it moves, its body carved from bones decorated with fine scrimshaw.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Scrimshaw Magic","kind":"Sp","details":"When a tupilaq is created, its creator can inscribe a single spell he knows (as long as that spell is no higher than 2nd level and requires no material components) into the tupilaq as a complex scrimshaw design. The tupilaq gains the ability to use that spell as a spell-like ability (CL 7th) three times per day. The tupilaq's creator can inscribe a new spell onto the tupilaq if he wishes, replacing the previous scrimshaw. Inscribing a new scrimshaw requires 24 hours of work and an expenditure of 500 gp in materials. The tupilaq presented here utilizes invisibility in this manner. Erase can destroy a tupilaq's scrimshaw if it fails a Fortitude save against the spell. If a tupilaq's scrimshaw is removed in this manner, it loses access to the spell as a spell-like ability, and seeks out its creator to attack and kill him. The tupilaq's creator becomes the target of the tupilaq's seek target ability in this case. If a tupilaq's creator is already dead, the tupilaq instead seeks out the nearest living creature and attacks this new target on sight, continuing this spree of murder until it is itself destroyed."},{"type":"Seek Target","kind":"Su","details":"A tupilaq's creator can place a drop of blood, lock of hair, or other portion of a creature's body in the tupilaq's maw as a standard action. From that point on, the tupilaq constantly knows what direction that creature is located in, and gains a +20 insight bonus on all Perception checks made to locate the creature. A new target cannot be assigned to a tupilaq in this manner until its previous target is dead."},{"type":"Shearing Jaws","kind":"Ex","details":"All tupilaqs are crafted with oversized jaws capable of tearing and pulling. A tupilaq applies twice its Strength modifier to damage with a successful bite attack and threatens a critical hit on a roll of 19-20. A tupilaq is treated as Large for all checks made to move a grappled opponent."}],"description":"Tupilaqs are small constructs crafted out of whale bones and whale teeth for the sole purpose of murdering the creator's enemies. A tupilaq's appearance can vary based on its construction, but all have prominent jaws and a small body with hands and ft. fit for swimming. A tupilaq usually stands 3 ft. tall and weighs only 30 pounds.\n\nTupilaqs must be created in secrecy-if any other person discovers the tupilaq is being created, the attempt to build the construct immediately fails. As part of its creation, the creator invites or lures a host spirit to possess the tupilaq. Most often, the animus of a tupilaq is that of a dead child or other small humanoid, and the parity of size between the new vessel and the spirit's previous body is what gives the creature a speed and agility on land and in water that is atypical for most constructs. This trapped spirit is also what makes a tupilaq so savage and murderous.\n\nConstruction\n\nA tupilaq is built from 30 pounds of whale bones, bound together with sinew worth 750 gp. When the creature's creation is complete, the sinew falls away and the bones fuse together to create the creature.\n\nTUPILAQ\n\nCL 8th; Price 21,000 gp\n\nConstruction\n\nRequirements Craft Construct, geas/quest, keen edge, locate creature, creator must be caster level 8th, creation must be done in complete secrecy; Skill Craft (scrimshaw) DC 20; Cost 10,875 gp","ecology":"","habitat_society":""}];
